-- Private API & Supabase usage metrics table + active rate-limit reader for /dev.

CREATE TABLE IF NOT EXISTS "public"."api_usage_events" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "provider" "text" NOT NULL,
    "endpoint" "text" NOT NULL,
    "source" "text" DEFAULT 'edge'::"text" NOT NULL,
    "status_code" integer,
    "outcome" "text" DEFAULT 'ok'::"text" NOT NULL,
    "duration_ms" integer,
    "request_count" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "api_usage_events_outcome_check" CHECK (("outcome" = ANY (ARRAY['ok'::"text", 'rate_limited'::"text", 'error'::"text"]))),
    CONSTRAINT "api_usage_events_request_count_check" CHECK (("request_count" >= 1))
);

ALTER TABLE "public"."api_usage_events" OWNER TO "postgres";

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'api_usage_events_pkey'
    ) THEN
        ALTER TABLE ONLY "public"."api_usage_events"
            ADD CONSTRAINT "api_usage_events_pkey" PRIMARY KEY ("id");
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS "api_usage_events_occurred_at_idx"
    ON "public"."api_usage_events" USING btree ("occurred_at" DESC);

CREATE INDEX IF NOT EXISTS "api_usage_events_provider_occurred_idx"
    ON "public"."api_usage_events" USING btree ("provider", "occurred_at" DESC);

ALTER TABLE "public"."api_usage_events" ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Admin can read api_usage_events" ON "public"."api_usage_events";
CREATE POLICY "Admin can read api_usage_events" ON "public"."api_usage_events"
    FOR SELECT
    USING ((SELECT "public"."is_admin"()));

DROP POLICY IF EXISTS "Admin can insert api_usage_events" ON "public"."api_usage_events";
CREATE POLICY "Admin can insert api_usage_events" ON "public"."api_usage_events"
    FOR INSERT
    WITH CHECK ((SELECT "public"."is_admin"()));

DROP POLICY IF EXISTS "Admin can delete api_usage_events" ON "public"."api_usage_events";
CREATE POLICY "Admin can delete api_usage_events" ON "public"."api_usage_events"
    FOR DELETE
    USING ((SELECT "public"."is_admin"()));

REVOKE ALL ON TABLE "public"."api_usage_events" FROM "anon";
REVOKE ALL ON TABLE "public"."api_usage_events" FROM "authenticated";

GRANT SELECT, INSERT, DELETE ON TABLE "public"."api_usage_events" TO "authenticated";
GRANT ALL ON TABLE "public"."api_usage_events" TO "service_role";
GRANT USAGE, SELECT ON SEQUENCE "public"."api_usage_events_id_seq" TO "authenticated";
GRANT ALL ON SEQUENCE "public"."api_usage_events_id_seq" TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_active_rate_limits"()
    RETURNS TABLE (
        "key" "text",
        "window_start" timestamp with time zone,
        "count" integer
    )
    LANGUAGE "plpgsql"
    SECURITY DEFINER
    SET "search_path" = "public"
    AS $$
BEGIN
    IF NOT (SELECT public.is_admin()) THEN
        RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
    END IF;

    RETURN QUERY
    SELECT rl.key, rl.window_start, rl.count
    FROM public.rate_limits rl
    WHERE rl.window_start >= now() - interval '5 minutes'
    ORDER BY rl.window_start DESC, rl.count DESC;
END;
$$;

ALTER FUNCTION "public"."get_active_rate_limits"() OWNER TO "postgres";

REVOKE ALL ON FUNCTION "public"."get_active_rate_limits"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "public"."get_active_rate_limits"() FROM "anon";
REVOKE ALL ON FUNCTION "public"."get_active_rate_limits"() FROM "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_active_rate_limits"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_active_rate_limits"() TO "service_role";
